"""Reviewed bilingual Core powers, checked against the supplied page images.

Do not copy the candidate OCR: its column boundaries, levels and trailing text
are unreliable. Keep saved power IDs and the existing selectable Portuguese name.
"""
import json, sys
from pathlib import Path

repo = Path(__file__).resolve().parent.parent
work = Path(sys.argv[1])
candidates = json.loads((work/'catalog/candidates.json').read_text(encoding='utf-8'))
source = next(s for s in json.loads((work/'pages/manifest.json').read_text(encoding='utf-8')) if s['id']=='core-v5')
rows=[]
def add(id,en,discipline,level,pages,pt,english,extra=None,aliases=None):
    old=next(c for c in candidates if c['book']=='core-v5' and c['id']==id)
    requirements={'disciplines':{discipline:level,**(extra or {})}}
    title_map={'Descrição':'Description','Custo':'Cost','Parada':'Dice Pool','Sistema':'System','Duração':'Duration','Exceções':'Exceptions','Resistência':'Resistance'}
    descriptions={locale:[{'title':title_map.get(k,k) if locale=='en' else k,'text':v} for k,v in values] for locale,values in [('pt-BR',pt),('en',english)]}
    for locale in descriptions:
        names={'Animalismo':'Animalism','Auspícios':'Auspex','Ofuscação':'Obfuscate','Dominação':'Dominate','Celeridade':'Celerity'}
        required=[f'{names.get(d,d) if locale=="en" else d} {n}' for d,n in requirements['disciplines'].items()]
        descriptions[locale].insert(1,{'title':'Requirements' if locale=='en' else 'Requisitos','text':(' and ' if locale=='en' else ' e ').join(required)+'.'})
        if discipline=='Animalismo':
            descriptions[locale].append({'title':'Discipline exceptions' if locale=='en' else 'Exceções da Disciplina','text':'Animalism powers involving animals normally affect vertebrates only. Using a power on herbivores adds 1 to the Difficulty of the associated Skill rolls. Unliving Hive extends earlier powers to insect swarms.' if locale=='en' else 'Poderes de Animalismo que envolvem animais normalmente só afetam vertebrados. Usar um poder em herbívoros aumenta em 1 a Dificuldade dos testes de Habilidades envolvidos. Enxame Não Vivo estende os poderes anteriores a enxames de insetos.'})
        if discipline=='Dominação':
            descriptions[locale].append({'title':'General Dominate rules' if locale=='en' else 'Regras gerais de Dominação','text':'Most powers require eye contact, held until the command is given unless interrupted. Catching an avoiding gaze uses Resolve + Intimidation against Wits + Awareness; closed or covered eyes cannot be caught. In combat or turmoil, targets must be attacking or directly interacting with the user. Commands must normally be spoken, heard and understood, unless a supernatural method such as Telepathy permits otherwise. Without Terminal Decree, obvious death or grave harm automatically fails. Other harmful commands, violations of Convictions, or harm to Touchstones and those relationships allow resistance under the individual power. Dominate cannot extract information or make someone do what ordinary instructions cannot achieve, such as sleep on command. A lower-generation vampire can spend 1 Willpower to completely negate Dominate by a higher-generation vampire. Total failure prevents the user from Dominating that target for the rest of the story. Use may cause Stains depending on Tenets.' if locale=='en' else 'A maioria dos poderes exige contato visual, mantido até a ordem salvo interrupção. Capturar um olhar que o evita exige Determinação + Intimidação contra Raciocínio + Percepção; olhos fechados ou vendados não podem ser capturados. Em combate ou tumulto, o alvo precisa estar atacando ou interagindo diretamente com o usuário. Ordens normalmente precisam ser faladas, ouvidas e compreendidas, salvo meio sobrenatural como Telepatia. Sem Decreto Terminal, morte óbvia ou ferimento grave fazem a ordem falhar automaticamente. Outros prejuízos, violar Convicções ou prejudicar Pilares e seus relacionamentos permitem resistência conforme o poder. Não extrai informações nem obriga ações impossíveis por instrução comum, como dormir sob comando. Vampiro de geração menor pode gastar 1 Vontade para anular completamente Dominação de geração maior. Falha total impede Dominar aquele alvo pelo resto da história. O uso pode causar Máculas conforme os Princípios.'})
    refs=sorted(set(pages+([247] if discipline=='Animalismo' else [257,258] if discipline=='Dominação' else [])))
    entry={'id':id,'kind':'power','names':{'pt-BR':old['name'],'en':en},'aliases':list(dict.fromkeys([old['name'],en]+(aliases or []))),'discipline':discipline,'level':level,'versions':[{'id':id+'-core','book':'core-v5','sourceTitle':'Livro Básico V5, pp. '+', '.join(str(p-2) for p in refs),'sourceLanguage':'pt-BR','pdfSha256':source['sha256'],'pages':[{'pdfPage':p,'printedPage':p-2} for p in refs],'requirements':requirements,'descriptions':descriptions}]}
    (repo/'scripts/reviewed-content'/('core-'+id+'.json')).write_text(json.dumps(entry,ensure_ascii=False,indent=2),encoding='utf-8')
    rows.append(entry)

add('bond-famulus','Bond Famulus','Animalismo',1,[247],[
('Descrição','Cria um vínculo mental com um animal transformado em fâmulo. Ele segue comandos verbais simples, como ficar ou vir, e defende a si e ao mestre; este poder sozinho não permite comunicação em mão dupla nem o obriga a atacar algo que normalmente evitaria.'),
('Custo','Alimente o animal com seu Sangue em três noites distintas, fazendo um Teste de Sangue em cada uma. Depois, a quantidade para sustentar seu estado de carniçal é insignificante. Quem começa o jogo com o poder já concluiu o processo e pode escolher um fâmulo.'),
('Parada','Carisma + Empatia com Animais, Dificuldade 2 para ordens simples sem Sussurros Selvagens; ordens mais complexas aumentam a Dificuldade.'),
('Sistema','Só pode ter um fâmulo, mas pode criar outro se ele morrer. Sussurros Selvagens e Comunhão de Espíritos não custam Sangue quando usados no próprio fâmulo.'),
('Duração','Só a morte desfaz o vínculo. O fâmulo não envelhece enquanto receber Sangue vampírico regularmente.')],[
('Descrição','Creates a mental bond with an animal famulus. It follows simple spoken commands such as stay or come and defends itself and its master. This power alone does not allow two-way communication or make it attack something it would normally avoid.'),
('Custo','Feed the animal your Blood on three separate nights, making one Rouse Check each night. Maintenance thereafter takes an insignificant amount of Blood. Characters starting with this power have already completed this process and may choose a famulus.'),
('Parada','Charisma + Animal Ken, Difficulty 2 for simple commands without Feral Whispers; complex commands raise the Difficulty.'),
('Sistema','Only one famulus at a time; another can be created if it dies. Using Feral Whispers or Subsume the Spirit on your own famulus has no Blood cost.'),
('Duração','Only death releases the bond. The famulus does not age while regularly receiving vampiric Blood.')],aliases=['Famulus Enlaçado','Fâmulo Enlaçado'])
add('sense-the-beast','Sense the Beast','Animalismo',1,[247],[
('Descrição','Percebe a Besta de mortais, vampiros e outros seres, revelando hostilidade e natureza sobrenatural.'),('Custo','Gratuito.'),('Parada','Determinação + Animalismo contra Autocontrole + Subterfúgio.'),('Sistema','Uma vitória revela se o alvo está pronto ou determinado a causar mal e se abriga uma Besta sobrenatural. Um crítico identifica o tipo exato de criatura, sua Fome ou equivalente e Ressonância. Pode ser usado ativamente ou avisar passivamente sobre intenções agressivas próximas.'),('Duração','Passiva.')],[
('Descrição','Senses the Beast in mortals, vampires and other beings, revealing hostility and supernatural nature.'),('Custo','Free.'),('Parada','Resolve + Animalism opposed by Composure + Subterfuge.'),('Sistema','A win reveals whether the target is ready or determined to cause harm and whether it harbors a supernatural Beast. A critical identifies the exact creature type, its Hunger or equivalent, and Resonance. The power can be used actively or passively warn of nearby aggressive intent.'),('Duração','Passive.')])
add('feral-whispers','Feral Whispers','Animalismo',2,[247,248],[
('Descrição','Permite conversar com animais e tentar persuadi-los a ajudar ou convocar um tipo de animal presente na região. Eles entendem assuntos dentro de sua experiência, raramente aceitam tarefas contrárias à natureza ou perigosas e se dispersam ou atacam se ameaçados.'),('Custo','Um Teste de Sangue por tipo de animal escolhido na cena: inclui uma convocação e comunicação ilimitada. Gratuito no próprio fâmulo.'),('Parada','Manipulação + Animalismo para persuadir; Carisma + Animalismo para convocar. Comunicação simples não exige teste.'),('Sistema','A Dificuldade de persuadir depende da tarefa: vigiar quem entra num parque, 3; defender um local com a própria vida, 6. Convocar depende da escassez local: só animais que estejam presentes podem responder. A margem determina a quantidade; um crítico chama a maioria ou todos os animais daquele tipo na região. Os convocados escutam o usuário.'),('Duração','Uma cena.')],[
('Descrição','Allows two-way conversation with animals, persuasion to perform services, or summoning one type of animal already in the area. Animals understand matters within their experience, rarely accept unnatural or dangerous tasks, and scatter or attack if threatened.'),('Custo','One Rouse Check per animal type chosen for the scene, including one summoning and unlimited communication. Free on your own famulus.'),('Parada','Manipulation + Animalism to persuade; Charisma + Animalism to summon. Simple communication needs no roll.'),('Sistema','Persuasion Difficulty depends on the task: watching who enters a park, 3; defending a place with its life, 6. Summoning Difficulty depends on local scarcity; only animals actually present can respond. The margin determines their number, with a critical summoning most or all of that type in the area. Summoned animals listen to the user.'),('Duração','One scene.')])
add('unliving-hive','Unliving Hive','Animalismo',3,[248],[
('Descrição','Estende a influência sobre animais a enxames de insetos, inclusive permitindo um enxame como fâmulo e abrigando-o dentro do corpo.'),('Custo','Nenhum custo adicional.'),('Sistema','Os poderes anteriores restritos a vertebrados passam a tratar um enxame de insetos como uma criatura. Um enxame enlaçado pode viver nas cavidades do corpo, oculto exceto a raios X, bebendo quantidades ínfimas de Sangue para sustentar-se indefinidamente. Tem Vitalidade 5 e 8 dados para resistir a ataques; Briga causa dano superficial, fogo e inseticida causam agravado. Causa pouco dano em combate, mas pode espionar, distrair uma pessoa envolta pelo enxame (−2 dados a qualquer rolagem) ou intimidar mortais (+1 a +3 dados de Intimidação conforme os insetos e as fobias do alvo). Outros usos criativos cabem ao grupo.'),('Duração','Passiva.')],[
('Descrição','Extends animal influence to insect swarms, including bonding a swarm as a famulus and housing it inside the body.'),('Custo','No additional cost.'),('Sistema','Earlier powers limited to vertebrates treat an insect swarm as one creature. A bonded swarm can nest in bodily cavities, hidden except from X-rays, taking tiny amounts of Blood to sustain itself indefinitely. It has Health 5 and 8 dice to resist attacks; Brawl inflicts Superficial damage, while fire and insecticide inflict Aggravated damage. It does little combat damage but can spy, distract one person surrounded by it (−2 dice to any roll), or intimidate mortals (+1 to +3 Intimidation dice depending on insects and phobias). The group can devise further creative uses.'),('Duração','Passive.')],{'Ofuscação':2})
add('quell-the-beast','Quell the Beast','Animalismo',3,[248,249],[
('Descrição','Com contato visual, intimida e adormece temporariamente a Besta do alvo. Mortais ficam apáticos e vampiros têm os impulsos bestiais suprimidos.'),('Custo','Um Teste de Sangue.'),('Parada','Carisma + Animalismo contra Vigor + Determinação.'),('Sistema','Uma vitória incapacita um mortal pela cena: ele só age para preservar a própria vida, sem agir contra o usuário ou outra pessoa. Um vampiro afetado não usa Impulso de Sangue e fica imune a críticos bestiais. Uma vitória crítica contra vampiro também encerra seu Frenesi.'),('Duração','Uma cena contra mortais; um turno mais a margem de vitória contra vampiros.')],[
('Descrição','Eye contact intimidates the target’s Beast into temporary slumber. Mortals become apathetic and vampires have their bestial impulses suppressed.'),('Custo','One Rouse Check.'),('Parada','Charisma + Animalism opposed by Stamina + Resolve.'),('Sistema','A win incapacitates a mortal for the scene: they act only to preserve their life, not against the user or anyone else. An affected vampire cannot Blood Surge and is immune to messy criticals. A critical win against a vampire also ends their frenzy.'),('Duração','One scene for mortals; one turn plus the winning margin for vampires.')])
add('animal-succulence','Animal Succulence','Animalismo',3,[249],[
('Descrição','Obtém mais sustento do sangue animal e absorve temporariamente uma característica ao consumir o próprio fâmulo.'),('Custo','Gratuito.'),('Sistema','Alimentar-se de animais sacia 1 Fome adicional; considere sua Potência de Sangue dois níveis abaixo ao determinar penalidades para saciar Fome com sangue animal. Consumir o próprio fâmulo sacia 4 Fome, qualquer que seja seu tamanho, mas nunca o último ponto. Isso também aumenta em 2 o Atributo mais associado ao animal, escolhido pelo Narrador: um gato pode dar Destreza ou Autocontrole; um cão, Carisma ou Determinação. O Narrador pode variar a recompensa, como +2 ao Atributo de paradas de percepção ou sabedoria ao consumir uma coruja.'),('Duração','Passiva. O bônus do fâmulo termina na próxima alimentação ou ao alcançar Fome 5.')],[
('Descrição','Gains extra nourishment from animal blood and temporarily absorbs a characteristic by consuming your own famulus.'),('Custo','Free.'),('Sistema','Feeding on animals slakes 1 additional Hunger; treat Blood Potency as two levels lower for penalties to slaking Hunger with animal blood. Consuming your own famulus slakes 4 Hunger regardless of size, but never the last point. It also increases the Attribute most associated with that animal by 2, chosen by the Storyteller: a cat might grant Dexterity or Composure; a dog, Charisma or Resolve. The Storyteller may vary the reward, such as +2 to the Attribute in perception or wisdom pools for an owl.'),('Duração','Passive. The famulus bonus ends at the next feeding or upon reaching Hunger 5.')])
add('subsume-spirit','Subsume the Spirit','Animalismo',4,[249],[
('Descrição','Transfere a mente para um animal, controlando-o e usando seus sentidos. O corpo vampírico fica imóvel como em Torpor.'),('Custo','Um Teste de Sangue; gratuito no próprio fâmulo.'),('Parada','Manipulação + Animalismo, Dificuldade 4.'),('Sistema','Uma vitória permite habitar o animal por uma cena; um crítico, indefinidamente. Para continuar durante o dia, é preciso permanecer acordado (p. 219). Ver o sol exige resistência ao Frenesi de Terror, embora a luz não fira o animal. O vampiro não percebe seu corpo, mas dano nele encerra o transe. A morte do animal também encerra o efeito e causa 1 dano agravado em Vontade ao usuário.'),('Duração','Uma cena; indefinida com vitória crítica, sujeita às condições acima.')],[
('Descrição','Transfers the mind into an animal, controlling it and using its senses. The vampire’s body remains motionless as if in torpor.'),('Custo','One Rouse Check; free on your own famulus.'),('Parada','Manipulation + Animalism, Difficulty 4.'),('Sistema','A win allows inhabiting the animal for one scene; a critical, indefinitely. Continuing by day requires staying awake (p. 219). Seeing the sun requires resisting terror frenzy, though sunlight does not harm the animal. The vampire is unaware of their body, but damage to it breaks the trance. The animal’s death also ends the power and inflicts 1 Aggravated Willpower damage on the user.'),('Duração','One scene; indefinite on a critical win, subject to the conditions above.')])
add('animal-dominion','Animal Dominion','Animalismo',5,[249],[
('Descrição','Comanda bandos de animais como extensões do próprio corpo, podendo exigir até que se sacrifiquem.'),('Custo','Dois Testes de Sangue.'),('Parada','Carisma + Animalismo; Dificuldade conforme os animais e a ordem.'),('Sistema','Escolha um tipo de animal presente. Mandar corvos procurar alguém que possam identificar tem Dificuldade 3; mandar cães num ataque suicida contra um vampiro tem Dificuldade 5. O poder não convoca animais, mas obriga os presentes a obedecer. Pode ordenar o retorno após a tarefa, se tiverem meios de voltar.'),('Duração','Uma cena ou até cumprir a ordem, o que ocorrer primeiro.')],[
('Descrição','Commands groups of animals as extensions of the user’s body, even ordering their sacrifice.'),('Custo','Two Rouse Checks.'),('Parada','Charisma + Animalism; Difficulty depends on animals and command.'),('Sistema','Choose one animal type present. Sending crows to search for someone they can identify is Difficulty 3; ordering dogs into a suicidal attack on a vampire is Difficulty 5. The power does not summon animals but compels those present to obey. They can be ordered to return after the task if able to do so.'),('Duração','One scene or until the command is fulfilled, whichever comes first.')])
add('drawing-out-beast','Drawing Out the Beast','Animalismo',5,[249,250],[
('Descrição','Projeta a própria Besta num mortal ou vampiro próximo, transferindo um Frenesi de Fúria ou Terror.'),('Custo','Um Teste de Sangue.'),('Parada','Raciocínio + Animalismo contra Autocontrole + Determinação do alvo, no lugar do teste de Vontade para resistir ao Frenesi.'),('Sistema','Sucesso faz o alvo entrar no Frenesi em seu lugar, atacando ou fugindo conforme o gatilho. Falha faz o usuário entrar em Frenesi como numa falha de resistência normal. Novos estímulos ainda podem provocar seu Frenesi; pode repetir enquanto puder fazer Testes de Sangue e houver alvos. Não transfere Frenesi de Fome.'),('Duração','A duração do Frenesi (p. 220).')],[
('Descrição','Projects the user’s Beast into a nearby mortal or vampire, transferring a fury or terror frenzy.'),('Custo','One Rouse Check.'),('Parada','Wits + Animalism opposed by the target’s Composure + Resolve, replacing the Willpower roll to resist frenzy.'),('Sistema','Success makes the target frenzy instead, attacking or fleeing according to the trigger. Failure makes the user frenzy as if the normal resistance roll had failed. Further stimuli can still trigger the user; the power can be repeated while Rouse Checks and targets remain available. It cannot transfer hunger frenzy.'),('Duração','The duration of the frenzy (p. 220).')])
add('heightened-senses','Heightened Senses','Auspícios',1,[251],[
('Descrição','Aguça os sentidos a níveis sobrenaturais, permitindo enxergar na escuridão total, ouvir ultrassons e farejar medo.'),('Custo','Gratuito; o uso prolongado pode exigir Vontade, a critério do Narrador.'),('Parada','Raciocínio + Determinação, Dificuldade 3 ou mais, para amortecer os sentidos diante de estímulos extremos.'),('Sistema','Adicione Auspícios a todas as rolagens de percepção. Estampidos, clarões ou odores pungentes exigem o teste acima; falha causa −3 dados em todas as rolagens de percepção pelo resto da cena.'),('Duração','Até desativar. Manter por mais de uma cena sem descanso, sobretudo em ambiente muito estimulante, pode custar Vontade.')],[
('Descrição','Sharpens the senses supernaturally, allowing sight in total darkness, ultrasonic hearing and smelling fear.'),('Custo','Free; prolonged use may require Willpower at the Storyteller’s discretion.'),('Parada','Wits + Resolve, Difficulty 3 or higher, to dampen the senses against extreme stimuli.'),('Sistema','Add Auspex to all perception rolls. Loud bangs, flashes or pungent odors require the roll above; failure inflicts −3 dice on all perception rolls for the rest of the scene.'),('Duração','Until deactivated. Use beyond one scene without rest, especially in highly stimulating surroundings, may cost Willpower.')])
add('sense-unseen','Sense the Unseen','Auspícios',1,[251],[
('Descrição','Detecta presenças sobrenaturais escondidas, como Ofuscação, observadores com Auspícios e fantasmas. O Narrador pode permitir detectar também feitiços ou rituais inativos.'),('Custo','Gratuito.'),('Parada','Raciocínio + Auspícios passivamente; Determinação + Auspícios ao procurar ativamente.'),('Sistema','O Narrador faz um teste oculto quando algo sobrenatural se esconde à vista, com Dificuldade escolhida por ele. Contra alguém tentando ocultar-se, pode pedir uma rolagem cega em conflito com a parada relevante: contra Ofuscação, por exemplo, Raciocínio + Auspícios contra Raciocínio + Ofuscação.'),('Duração','Passiva.')],[
('Descrição','Detects hidden supernatural presences such as Obfuscate, Auspex observers and ghosts. The Storyteller may also allow detection of inactive spells or rituals.'),('Custo','Free.'),('Parada','Wits + Auspex passively; Resolve + Auspex when actively searching.'),('Sistema','The Storyteller makes a hidden roll when something supernatural hides in plain sight, setting the Difficulty. Against an entity actively concealing itself, a blind roll may oppose its relevant pool: detecting Obfuscate, for example, uses Wits + Auspex against Wits + Obfuscate.'),('Duração','Passive.')])
add('premonition','Premonition','Auspícios',2,[251,252],[
('Descrição','Oferece pressentimentos, inspirações ou visões imprecisas que revelam uma pista, verdade ou perigo.'),('Custo','Gratuito quando o Narrador concede a visão; um Teste de Sangue para provocá-la.'),('Parada','Determinação + Auspícios ao provocar a visão.'),('Sistema','O Narrador concede uma dica quando apropriado e pode usá-la para mover a história ou revelar uma pista ignorada. O limite sugerido é uma premonição por cena, mesmo se vários personagens tiverem o poder. Para provocá-la, concentre-se num alvo, faça o Teste de Sangue e role; os sucessos determinam a profundidade da revelação sobre ele, se houver alguma.'),('Duração','Passiva.')],[
('Descrição','Offers hunches, sudden insights or imprecise visions revealing a clue, truth or danger.'),('Custo','Free when granted by the Storyteller; one Rouse Check to provoke a vision.'),('Parada','Resolve + Auspex when provoking a vision.'),('Sistema','The Storyteller grants a helpful hint when appropriate, allowing the story to move or an overlooked clue to emerge. The suggested limit is one premonition per scene even with multiple characters possessing the power. To provoke one, concentrate on a target, make the Rouse Check and roll; successes determine the depth of revelation about it, if any.'),('Duração','Passive.')])
add('share-senses','Share the Senses','Auspícios',3,[252],[
('Descrição','Percebe por um, vários ou todos os sentidos de outro mortal ou vampiro, conservando a percepção dos próprios arredores. Exige linha de visão para iniciar num estranho; pode funcionar à distância em quem ainda tenha seu Sangue no corpo.'),('Custo','Um Teste de Sangue.'),('Parada','Determinação + Auspícios, Dificuldade 3; pode aumentar por distrações, distância ou quantidade de Sangue restante no alvo.'),('Sistema','O alvo normalmente ignora a intrusão, mas Sentir o Invisível pode detectá-la. Para expulsar o passageiro, vence um conflito de Raciocínio + Determinação contra Raciocínio + Determinação. Se expulso, o usuário não pode tentar compartilhar os sentidos novamente até a próxima noite.'),('Duração','Uma cena.')],[
('Descrição','Experiences one, several or all senses of another mortal or vampire while retaining awareness of the user’s own surroundings. Starting on a stranger requires line of sight; it can work at range on someone still carrying the user’s Blood.'),('Custo','One Rouse Check.'),('Parada','Resolve + Auspex, Difficulty 3; distractions, distance or the remaining amount of Blood in the target can raise it.'),('Sistema','The target is usually unaware, but Sense the Unseen can detect the intrusion. To expel the passenger, win a Wits + Resolve versus Wits + Resolve contest. An expelled user cannot attempt to share senses again until the next night.'),('Duração','One scene.')])
add('scry-soul','Scry the Soul','Auspícios',3,[252],[
('Descrição','Examina a aura de uma pessoa para descobrir emoções, Ressonância e características sobrenaturais. Pode procurar uma condição específica numa multidão, mas nesse caso não recebe outros tipos de informação.'),('Custo','Um Teste de Sangue.'),('Parada','Inteligência + Auspícios contra Autocontrole + Subterfúgio; ao examinar multidão, Dificuldade conforme quantidade de pessoas, distrações e característica procurada.'),('Sistema','Numa vitória, o Narrador responde com verdade a uma pergunta por ponto de margem sobre a aura ou psique: estado emocional; Ressonância do sangue; natureza sobrenatural (vampiro, lobisomem, carniçal etc.); influência de Feitiçaria de Sangue ou outra magia; Diablerie no último ano. Um crítico revela algo inesperado escolhido pelo Narrador. Numa multidão, achar um vampiro numa sala pode ser Dificuldade 3; a pessoa mais inquieta numa rave, 6 ou mais.'),('Duração','Um turno, ou conforme o Narrador.')],[
('Descrição','Examines a person’s aura for emotions, Resonance and supernatural traits. A crowd can be scanned for one specific condition, but that scan provides no other information.'),('Custo','One Rouse Check.'),('Parada','Intelligence + Auspex opposed by Composure + Subterfuge; for crowds, Difficulty depends on numbers, distractions and the trait sought.'),('Sistema','On a win, the Storyteller truthfully answers one question per point of margin about aura or psyche: emotional state; blood Resonance; supernatural nature (vampire, werewolf, ghoul, etc.); influence of Blood Sorcery or other magic; diablerie within the last year. A critical reveals something unexpected chosen by the Storyteller. In a crowd, finding a vampire in a room might be Difficulty 3; finding the most agitated person at a rave, 6 or more.'),('Duração','One turn, or as determined by the Storyteller.')])
add('spirits-touch','Spirit’s Touch','Auspícios',4,[252],[
('Descrição','Tocar um objeto inanimado ou o chão de um local revela resíduos emocionais de quem o manuseou ou visitou, incluindo ações e circunstâncias. As impressões raramente são claras, mas vão além da perícia forense comum.'),('Custo','Um Teste de Sangue.'),('Parada','Inteligência + Auspícios, Dificuldade conforme a informação procurada.'),('Sistema','Perceber a emoção de quem usou uma arma de assassinato há poucos dias pode ter Dificuldade 3; o ambiente de escrita de uma carta de 300 anos, 6 ou mais. Cada ponto de margem permite sentir aproximadamente mais um portador anterior e um conjunto adicional de circunstâncias, retrocedendo a partir do mais recente.'),('Duração','Um turno.')],[
('Descrição','Touching an inanimate object or the ground at a location reveals emotional residue of handlers or visitors, including actions and circumstances. Impressions are rarely clear but go beyond ordinary forensic examination.'),('Custo','One Rouse Check.'),('Parada','Intelligence + Auspex, Difficulty based on the information sought.'),('Sistema','Sensing the emotion of someone who used a murder weapon days ago might be Difficulty 3; the setting where a 300-year-old letter was written, 6 or more. Each point of margin reveals approximately one additional previous handler and set of circumstances, working backward from the most recent.'),('Duração','One turn.')],aliases=["Spirit's Touch"])
add('clairvoyance','Clairvoyance','Auspícios',5,[253],[
('Descrição','Em transe leve e de olhos fechados, reúne em minutos informações sobre aproximadamente uma quadra, ou área maior ao ar livre ou menos populosa, e pode acompanhar acontecimentos incomuns.'),('Custo','Um Teste de Sangue.'),('Parada','Inteligência + Auspícios; Dificuldade conforme segurança e atividade da área. Some o valor base de Refúgio ao usar no próprio refúgio.'),('Sistema','Na própria mansão, Dificuldade 3; numa área urbana desconhecida e tumultuada, 7 ou mais. O Narrador responde aproximadamente uma pergunta por ponto de margem sobre movimento, o que foi visto ou ouvido, fofocas, surpresas e impressões. Informação deliberadamente escondida pode consumir mais de um ponto. Um crítico revela algo importante, independentemente das perguntas, se existir algo a revelar. Também pode vigiar eventos em curso, mas precisa permanecer na área enquanto o fizer.'),('Duração','Alguns minutos para obter informações; até uma noite para vigilância.')],[
('Descrição','With eyes closed in a light trance, gathers information in minutes about roughly a city block, or a larger outdoor or less populated area, and can monitor unusual events.'),('Custo','One Rouse Check.'),('Parada','Intelligence + Auspex; Difficulty depends on local security and activity. Add the base Haven rating when using it in your own haven.'),('Sistema','Your own mansion might be Difficulty 3; an unfamiliar, tumultuous urban area, 7 or more. The Storyteller answers approximately one question per point of margin about movement, sights or sounds, gossip, surprises and impressions. Deliberately hidden information may consume more than one point. A critical reveals something major independently of the questions, if anything exists to reveal. Ongoing events can also be monitored, but the user must remain in the area throughout.'),('Duração','A few minutes for information gathering; up to one night for surveillance.')])
add('possession','Possession','Auspícios',5,[253],[
('Descrição','Toma o corpo de um mortal, deixando a mente dele inacessível e o próprio corpo em transe. Só funciona em mortais; carniçais precisam estar Enlaçados ao usuário.'),('Custo','Dois Testes de Sangue.'),('Parada','Determinação + Auspícios contra Determinação + Inteligência, com contato visual inicial conforme Dominação (p. 254).'),('Sistema','Falha total torna a vítima imune a novas tentativas pelo restante da história. O corpo vampírico fica inconsciente dos arredores e de sua condição, exceto dano agravado, que encerra o efeito. Pode usar Auspícios, Presença e Dominação pelo hospedeiro. Permanecer durante o dia exige ficar acordado (p. 219); falha encerra a possessão. Quando o hospedeiro sofre dano agravado, teste Determinação + Auspícios, Dificuldade 2 + dano sofrido, para manter o controle. A morte dele causa imediatamente 3 danos agravados em Vontade ao usuário. Não lê pensamentos nem adquire Habilidades ou maneirismos: usa as próprias Habilidades. Para imitar a vítima, Manipulação + Performance contra Raciocínio + Sagacidade. O Narrador deve considerar Máculas pela violação da vítima.'),('Duração','Até terminar voluntariamente ou por uma das condições acima.')],[
('Descrição','Takes over a mortal body while leaving its mind inaccessible and the vampire’s own body in a trance. Only works on mortals; ghouls must be Blood Bound to the user.'),('Custo','Two Rouse Checks.'),('Parada','Resolve + Auspex opposed by Resolve + Intelligence, initially requiring eye contact under Dominate (p. 254).'),('Sistema','A total failure makes the victim immune to further attempts for the rest of the story. The vampire’s body is unaware of surroundings or condition except Aggravated damage, which ends possession. Auspex, Presence and Dominate can be used through the host. Continuing by day requires staying awake (p. 219); failure ends possession. When the host takes Aggravated damage, roll Resolve + Auspex, Difficulty 2 + damage suffered, to retain control. The host’s death immediately inflicts 3 Aggravated Willpower damage on the user. It grants no mind reading, Skills or mannerisms: use your own Skills. Impersonation uses Manipulation + Performance opposed by Wits + Insight. The Storyteller should consider Stains for violating the victim.'),('Duração','Until voluntarily ended or interrupted by the conditions above.')],{'Dominação':3})
add('telepathy','Telepathy','Auspícios',5,[254],[
('Descrição','Lê pensamentos e projeta os próprios pensamentos noutras mentes. Mentes vampíricas involuntárias exigem esforço adicional.'),('Custo','Um Teste de Sangue; mais 1 Vontade antes de rolar contra vampiro involuntário.'),('Parada','Determinação + Auspícios contra Raciocínio + Subterfúgio para ler uma mente involuntária.'),('Sistema','Projetar pensamentos em mortal ou vampiro não exige rolagem, mas requer linha de visão. Ler um mortal à vista exige contato visual e o conflito acima, salvo se ele consentir, quando não há rolagem. Uma vitória revela pensamentos superficiais como imagens; margens maiores permitem buscar lembranças distantes ou enterradas. Um crítico fornece uma visão coerente dos pensamentos e intenções atuais. Contra vampiro involuntário, pague também a Vontade antes do conflito.'),('Duração','Aproximadamente um minuto por Teste de Sangue; uma cena completa com alvo voluntário.')],[
('Descrição','Reads thoughts and projects the user’s own thoughts into other minds. Unwilling vampiric minds require additional effort.'),('Custo','One Rouse Check; additionally spend 1 Willpower before rolling against an unwilling vampire.'),('Parada','Resolve + Auspex opposed by Wits + Subterfuge to read an unwilling mind.'),('Sistema','Projecting thoughts to a mortal or vampire requires no roll but needs line of sight. Reading a visible mortal requires eye contact and the contest above, unless they consent, in which case no roll is needed. A win reveals surface thoughts as images; greater margins allow probing distant or buried memories. A critical gives a coherent overview of current thoughts and intentions. Against an unwilling vampire, also pay the Willpower before the contest.'),('Duração','Approximately one minute per Rouse Check; a full scene with a willing target.')])

add('cats-grace','Cat’s Grace','Celeridade',1,[254],[
('Descrição','Equilíbrio e graça sobrenaturais permitem correr sobre saliências, cabos e suportes estreitos.'),('Custo','Gratuito.'),('Sistema','Sucesso automático em testes de Destreza ou Atletismo para manter o equilíbrio. O suporte ainda precisa aguentar seu peso.'),('Duração','Passiva.')],[
('Descrição','Supernatural balance and grace allow running along ledges, wires and narrow supports.'),('Custo','Free.'),('Sistema','Automatically succeeds on Dexterity or Athletics rolls to maintain balance. The support must still bear the user’s weight.'),('Duração','Passive.')],aliases=["Cat's Grace"])
add('rapid-reflexes','Rapid Reflexes','Celeridade',1,[254,255],[
('Descrição','Percepção e reação sobre-humanas permitem acompanhar projéteis e reagir mesmo sem cobertura.'),('Custo','Gratuito.'),('Sistema','Não sofre penalidade na parada de defesa por falta de cobertura contra Armas de Fogo. Pode realizar gratuitamente uma ação menor de até dois dados por turno, como preparar ou recarregar arma (p. 298).'),('Duração','Passiva.')],[
('Descrição','Superhuman perception and reaction allow tracking projectiles and reacting without cover.'),('Custo','Free.'),('Sistema','Takes no defense-pool penalty for lacking cover against Firearms. May freely perform one minor action worth up to two dice per turn, such as readying or reloading a weapon (p. 298).'),('Duração','Passive.')])
add('fleetness','Fleetness','Celeridade',2,[255],[
('Descrição','Move-se e reage com velocidade espantosa.'),('Custo','Um Teste de Sangue.'),('Sistema','Some Celeridade a testes de Destreza fora de combate. Uma vez por turno, também pode somá-la à defesa com Destreza + Atletismo.'),('Duração','Uma cena.')],[
('Descrição','Moves and reacts with astonishing speed.'),('Custo','One Rouse Check.'),('Sistema','Add Celerity to non-combat Dexterity tests. Once per turn, also add it when defending with Dexterity + Athletics.'),('Duração','One scene.')])
add('blink','Blink','Celeridade',3,[255],[
('Descrição','Avança ou foge num piscar, parecendo quase teleportar-se e deixando só uma rajada de vento.'),('Custo','Um Teste de Sangue.'),('Parada','Destreza + Atletismo em terreno perigoso; outras disputas conforme o Narrador.'),('Sistema','Percorra até 50 metros em linha reta até um alvo e ainda realize uma ação no turno. Terreno perigoso exige teste para não tropeçar e parar no caminho. Disputas podem decidir uma corrida por objeto ou ação. Ao avançar para atacar, age como se já estivesse em combate com o inimigo no início do turno. Exemplo: cruzar terreno perigoso antes do tiro pode exigir Destreza + Atletismo contra Destreza + Armas de Fogo; o vencedor age primeiro e o outro age depois.'),('Duração','Um turno.')],[
('Descrição','Closes distance or escapes in a blink, almost appearing to teleport and leaving a gust of wind.'),('Custo','One Rouse Check.'),('Parada','Dexterity + Athletics on dangerous terrain; other contests as needed by the Storyteller.'),('Sistema','Move up to 50 meters in a straight line to a target and still perform an action that turn. Dangerous terrain requires a roll to avoid stumbling and stopping en route. Contests may decide races for an object or action. When moving to attack, act as though already engaged with that enemy at the turn’s start. For example, crossing dangerous ground before a shot may use Dexterity + Athletics against Dexterity + Firearms; the winner acts first and the other acts afterward.'),('Duração','One turn.')],aliases=['Piscadela'])
add('traversal','Traversal','Celeridade',3,[255,256],[
('Descrição','Corre ou escala superfícies verticais e até líquidos com impulso. Não permite caminhar sobre água nem concede aderência de inseto.'),('Custo','Um Teste de Sangue.'),('Parada','Destreza + Atletismo, Dificuldade 3 (inclinação com tração) a 6 (vertical lisa ou água), conforme superfície e ângulo.'),('Sistema','A margem amplia a distância: 0 alcança alvo próximo; 1 alcança alvo mais distante, e assim por diante. O Narrador deve avisar antes se estiver longe demais. Como referência, mais de 60 metros sobre água ou 30 andares provavelmente excedem o alcance.'),('Duração','Um turno.')],[
('Descrição','Runs or climbs vertical surfaces and even liquids with a running start. It grants neither walking on water nor insect-like adhesion.'),('Custo','One Rouse Check.'),('Parada','Dexterity + Athletics, Difficulty 3 (incline with traction) to 6 (smooth vertical surface or water), depending on surface and angle.'),('Sistema','Margin increases distance: 0 reaches a nearby target; 1 a more distant target, and so on. The Storyteller must warn beforehand if a target is too far. As a guideline, more than 60 meters over water or 30 building stories probably exceeds its range.'),('Duração','One turn.')])
add('draught-elegance','Draught of Elegance','Celeridade',4,[256],[
('Descrição','O Sangue concede Celeridade temporária a quem o bebe. Beber diretamente também representa um passo para o Laço de Sangue.'),('Custo','Um Teste de Sangue.'),('Sistema','Quem bebe diretamente uma quantidade equivalente a um Teste de Sangue recebe Celeridade igual à metade da Celeridade do doador, arredondada para baixo. Recebe os mesmos poderes não amálgama do doador até esse nível.'),('Duração','Uma noite; para vampiros, até a próxima alimentação ou Fome 5.')],[
('Descrição','The Blood grants temporary Celerity to its drinker. Drinking directly also takes a step toward a Blood Bond.'),('Custo','One Rouse Check.'),('Sistema','Drinking directly an amount equivalent to one Rouse Check grants Celerity equal to half the donor’s rating, rounded down. The drinker gains the donor’s same non-Amalgam powers up to that level.'),('Duração','One night; for vampires, until their next feeding or Hunger 5.')])
add('unerring-aim','Unerring Aim','Celeridade',4,[256],[
('Descrição','Mira e dispara ou arremessa como se o alvo estivesse parado.'),('Custo','Um Teste de Sangue.'),('Sistema','Ative antes de um ataque à distância. O alvo não rola defesa ou esquiva; faça o ataque contra Dificuldade 1. Um oponente com Celeridade 5 pode anular isso com seu próprio Teste de Sangue e defender-se normalmente.'),('Duração','Um ataque.')],[
('Descrição','Aims and fires or throws as though the target were motionless.'),('Custo','One Rouse Check.'),('Sistema','Activate before a ranged attack. The target makes no defense or dodge roll; attack at Difficulty 1. An opponent with Celerity 5 can negate this with their own Rouse Check and defend normally.'),('Duração','One attack.')],{'Auspícios':2})
add('split-second','Split Second','Celeridade',5,[256],[
('Descrição','A velocidade física acompanha a percepção acelerada, permitindo reagir imediatamente a acontecimentos.'),('Custo','Um Teste de Sangue.'),('Sistema','Dentro do razoável, pode substituir a narração de eventos: passar por uma porta antes de fechar, evitar uma emboscada já iniciada ou sair de uma explosão. A ação deve ser plausível e levar no máximo alguns segundos reais. O Narrador determina quais testes de Habilidade, se houver, são necessários para realizá-la.'),('Duração','Aproximadamente uma ação, conforme o Narrador.')],[
('Descrição','Physical speed matches accelerated perception, allowing immediate reactions to events.'),('Custo','One Rouse Check.'),('Sistema','Within reason, override the narration of events: pass a door before it closes, evade an ambush already begun, or move clear of an explosion. The action must be plausible and take no more than a few real seconds. The Storyteller decides which Skill rolls, if any, are needed to accomplish it.'),('Duração','Approximately one action, as determined by the Storyteller.')])
add('lightning-strike','Lightning Strike','Celeridade',5,[256],[
('Descrição','Ataca com punhos ou armas brancas rápido demais para o oponente se defender.'),('Custo','Um Teste de Sangue.'),('Sistema','Ative antes de atacar com Briga ou Armas Brancas. O alvo não rola defesa ou esquiva; faça o ataque contra Dificuldade 1. Um oponente com Celeridade 5 pode anular isso com seu próprio Teste de Sangue e defender-se normalmente.'),('Duração','Um ataque.')],[
('Descrição','Strikes with fists or melee weapons too fast for the opponent to defend.'),('Custo','One Rouse Check.'),('Sistema','Activate before a Brawl or Melee attack. The target makes no defense or dodge roll; attack at Difficulty 1. An opponent with Celerity 5 can negate this with their own Rouse Check and defend normally.'),('Duração','One attack.')])
add('compel','Compel','Dominação',1,[258],[
('Descrição','Após contato visual, emite uma ordem de até uma frase curta, com uma ação executável em um turno e obedecida literalmente. Ambiguidade pode produzir resultado inesperado ou apenas confundir e falhar, conforme o Narrador.'),('Custo','Gratuito.'),('Parada','Carisma + Dominação contra Inteligência + Determinação.'),('Sistema','Não exige teste contra mortal despreparado. Há conflito contra vítima resistente, vampiro ou alguém já Dominado na mesma cena, e para ordens contrárias à natureza da vítima.'),('Duração','No máximo uma cena; a ação ordenada deve caber num turno.')],[
('Descrição','After eye contact, issues a command no longer than a short sentence, containing one action achievable in a turn and obeyed literally. Ambiguity can produce unexpected results or simply confuse and fail, as the Storyteller decides.'),('Custo','Free.'),('Parada','Charisma + Dominate opposed by Intelligence + Resolve.'),('Sistema','No roll against an unprepared mortal. A contest is required against a resisting victim, vampire, someone already Dominated that scene, or for commands contrary to the victim’s nature.'),('Duração','No more than one scene; the commanded action must fit in one turn.')])
add('cloud-memory','Cloud Memory','Dominação',1,[258],[
('Descrição','Ao dizer “Esqueça!”, apaga o momento atual e os últimos minutos, o bastante para ocultar uma alimentação superficial ou encontro casual. Não cria lembranças novas; se pressionada, a vítima percebe o apagão.'),('Custo','Gratuito.'),('Parada','Carisma + Dominação contra Raciocínio + Determinação.'),('Sistema','Não exige teste contra mortal despreparado. Vítima resistente ou vampiro exige o conflito acima.'),('Duração','Indefinida.')],[
('Descrição','Saying “Forget!” erases the current moment and the last few minutes, enough to hide a shallow feeding or casual encounter. It creates no replacement memories; questioning reveals a blackout.'),('Custo','Free.'),('Parada','Charisma + Dominate opposed by Wits + Resolve.'),('Sistema','No roll against an unprepared mortal. A resisting victim or vampire requires the contest above.'),('Duração','Indefinite.')])
add('dementation','Dementation','Dominação',2,[258],[
('Descrição','Uma conversa casual esconde influência que faz os conflitos internos da vítima consumirem sua razão.'),('Custo','Um Teste de Sangue por cena; cada vítima adicional exige seu próprio Teste de Sangue.'),('Parada','Manipulação + Dominação contra Autocontrole + Inteligência.'),('Sistema','Depois de começar a conversa, pode atacar um indivíduo por turno nesse conflito, causando dano superficial em Vontade. Mortal Debilitado pelo poder sofre crise nervosa ou surto psicótico conforme sua personalidade e talvez Ressonância. Vampiro Debilitado sofre imediatamente uma Compulsão escolhida pelo usuário.'),('Duração','Uma cena.')],[
('Descrição','A casual conversation conceals influence that lets the victim’s inner conflicts overwhelm their reason.'),('Custo','One Rouse Check per scene; each additional victim requires their own Rouse Check.'),('Parada','Manipulation + Dominate opposed by Composure + Intelligence.'),('Sistema','After starting a conversation, attack one individual per turn with this contest, inflicting Superficial Willpower damage. A mortal Impaired by the power suffers a nervous breakdown or psychotic episode shaped by personality and possibly Resonance. A vampire Impaired by it immediately suffers a Compulsion chosen by the user.'),('Duração','One scene.')],{'Ofuscação':2})
add('mesmerize','Mesmerize','Dominação',2,[258,259],[
('Descrição','Dá ordens complexas enquanto mantém o olhar da vítima e há silêncio para ouvi-las. Ela executa imediatamente o melhor que puder; condições futuras não são permitidas, pois exigem cognição.'),('Custo','Um Teste de Sangue.'),('Parada','Manipulação + Dominação contra Inteligência + Determinação.'),('Sistema','Não exige teste contra mortal despreparado. Exige conflito contra vítima resistente ou vampiro, e para comandos contrários à natureza da vítima.'),('Duração','Até cumprir a ordem ou terminar a cena, o que ocorrer primeiro.')],[
('Descrição','Gives complex commands while holding the victim’s gaze and with enough quiet to be heard. They immediately perform them as best they can; future conditions are not allowed because they require cognition.'),('Custo','One Rouse Check.'),('Parada','Manipulation + Dominate opposed by Intelligence + Resolve.'),('Sistema','No roll against an unprepared mortal. A contest is required against a resisting victim or vampire, and for commands contrary to the victim’s nature.'),('Duração','Until the command is completed or the scene ends, whichever comes first.')])
add('submerged-directive','Submerged Directive','Dominação',3,[259],[
('Descrição','Permite implantar, com Mesmerismo, uma sugestão pós-hipnótica dormente até um gatilho, como data, pessoa ou frase. Só uma sugestão por vítima; ela não expira e pode permanecer por anos.'),('Custo','Nenhum custo adicional ao Mesmerismo.'),('Parada','Como Mesmerismo: Manipulação + Dominação contra Inteligência + Determinação, quando necessário.'),('Sistema','Use as regras de Mesmerismo. O Narrador pode rolar em segredo: não há como saber se funcionou antes de o gatilho ocorrer.'),('Duração','Passiva; a sugestão permanece até seu gatilho.')],[
('Descrição','Allows Mesmerize to implant a dormant post-hypnotic suggestion triggered by a date, person, phrase or other condition. Only one suggestion per victim; it never expires and may remain for years.'),('Custo','No additional cost beyond Mesmerize.'),('Parada','As Mesmerize: Manipulation + Dominate opposed by Intelligence + Resolve when needed.'),('Sistema','Use Mesmerize rules. The Storyteller may roll secretly: success cannot be known until the trigger occurs.'),('Duração','Passive; the suggestion persists until triggered.')])
add('forgetful-mind','The Forgetful Mind','Dominação',3,[259],[
('Descrição','Reescreve fragmentos de memória enquanto mantém o olhar e a atenção total, sem interrupções. Descreve verbalmente novas lembranças aceitas como próprias pela vítima; não permite consultar as memórias verdadeiras.'),('Custo','Um Teste de Sangue.'),('Parada','Manipulação + Dominação contra Inteligência + Determinação.'),('Sistema','Cada ponto de margem permite adicionar ou remover uma memória extra. Edições comuns são vagas e podem ser desmascaradas sob interrogatório minucioso. Um crítico cria uma gravação impecável, tão real quanto uma lembrança verdadeira.'),('Duração','Indefinida.')],[
('Descrição','Rewrites fragments of memory while holding the victim’s gaze and full uninterrupted attention. Verbally described replacement memories are accepted as their own; it cannot inspect true memories.'),('Custo','One Rouse Check.'),('Parada','Manipulation + Dominate opposed by Intelligence + Resolve.'),('Sistema','Each point of margin allows adding or removing an additional memory. Ordinary edits are vague and can be exposed by close questioning. A critical produces a flawless recording as real as a genuine memory.'),('Duração','Indefinite.')],aliases=['A Mente Esquecida'])
add('rationalize','Rationalize','Dominação',4,[259],[
('Descrição','A vítima acredita ter agido por vontade própria sob Dominação e defende até ações absurdas. Exposição prolongada pode provocar traumas mentais graves.'),('Custo','Nenhum custo adicional.'),('Parada','Raciocínio + Percepção, Dificuldade 5, para a vítima pressionada sobre a crença.'),('Sistema','Sucesso nesse teste faz a vítima questionar a própria afirmação e, possivelmente, sua sanidade.'),('Duração','Indefinida.')],[
('Descrição','The victim believes actions taken under Dominate were their own choice and defends even absurd behavior. Prolonged exposure can cause severe mental trauma.'),('Custo','No additional cost.'),('Parada','Wits + Awareness, Difficulty 5, for a victim pressed about the belief.'),('Sistema','Success makes the victim question their claim and possibly their sanity.'),('Duração','Indefinite.')])
add('terminal-decree','Terminal Decree','Dominação',5,[259],[
('Descrição','Remove a barreira de autopreservação: pode ordenar ferimentos ou morte, inclusive exposição de vampiros a fogo ou sol.'),('Custo','Nenhum custo adicional de Fome; o custo em Humanidade pode ser grave.'),('Sistema','Ordens terminais passam a permitir resistência conforme a parada de cada poder usado, em vez de falharem automaticamente.'),('Duração','Passiva.')],[
('Descrição','Removes the self-preservation barrier, allowing orders of injury or death, including exposing vampires to fire or sunlight.'),('Custo','No additional Hunger cost; the Humanity cost can be severe.'),('Sistema','Terminal commands now allow resistance using the individual power’s pool instead of automatically failing.'),('Duração','Passive.')])
add('mass-manipulation','Mass Manipulation','Dominação',5,[259],[
('Descrição','Amplia outros poderes de Dominação para ordenar grupos inteiros de mortais ou vampiros e manipular suas memórias.'),('Custo','Um Teste de Sangue além do custo do poder ampliado.'),('Sistema','Todas as vítimas precisam ver os olhos do usuário. Faça os testes exigidos pelo poder contra o oponente mais forte do grupo.'),('Duração','A mesma do poder ampliado.')],[
('Descrição','Extends other Dominate powers to command groups of mortals or vampires and manipulate their memories.'),('Custo','One Rouse Check in addition to the amplified power’s cost.'),('Sistema','Every victim must see the user’s eyes. Make any rolls required by the power against the strongest opponent in the group.'),('Duração','As the amplified power.')])

print(f'{len(rows)} Core powers reviewed against PDF pages 247–259')
